//! 包管理器 —— 仓库索引、依赖解析与包安装。 //! //! 提供 `PackageManager`：刷新仓库索引、搜索、安装、移除、升级、 //! 列出已安装包。依赖解析使用拓扑排序并检测循环依赖；安装过程 //! 模拟「下载 → 校验和 → 解压 → 运行安装脚本」，已安装包记录到本地 //! JSON 包数据库。与 `kernel/pkg` 的轻量 `PkgStore` 并行存在，不替换。 //! //! 本模块不依赖外部 crates（无 serde），JSON 读写采用手写最小实现， //! 网络下载被模拟为本地缓存，因而可在用户态宏内核原型中脱网运行。  use std::collections::{BTreeMap, BTreeSet, HashMap}; use std::fs; use std::path::{Path, PathBuf};  // ======================================================================== // 错误 // ========================================================================  /// 包管理器错误。 #[derive(Clone, Debug, PartialEq, Eq)] pub enum PkgError {     /// 包在仓库中不存在。     NotFound { name: String },     /// 包已安装。     AlreadyInstalled { name: String },     /// 依赖缺失。     DependencyMissing { name: String, dep: String },     /// 依赖版本不满足。     DependencyUnsatisfied { name: String, dep: String, want: String, have: Option<String> },     /// 检测到循环依赖。     CycleDetected { cycle: Vec<String> },     /// 下载失败（模拟）。     DownloadFailed { url: String },     /// 校验和不匹配。     ChecksumMismatch { name: String, expect: String, got: String },     /// 安装失败。     InstallFailed { name: String, reason: String },     /// 仓库无效。     InvalidRepo { reason: String },     /// IO 错误。     Io { reason: String }, }  impl std::fmt::Display for PkgError {     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {         match self {             PkgError::NotFound { name } => write!(f, "包 {} 不存在于仓库", name),             PkgError::AlreadyInstalled { name } => write!(f, "包 {} 已安装", name),             PkgError::DependencyMissing { name, dep } => {                 write!(f, "包 {} 缺少依赖 {}", name, dep)             }             PkgError::DependencyUnsatisfied { name, dep, want, have } => {                 write!(                     f,                     "包 {} 依赖 {} 需要 {}，当前 {}",                     name,                     dep,                     want,                     have.as_deref().unwrap_or("<未安装>")                 )             }             PkgError::CycleDetected { cycle } => {                 write!(f, "检测到循环依赖: {}", cycle.join(" -> "))             }             PkgError::DownloadFailed { url } => write!(f, "下载失败: {}", url),             PkgError::ChecksumMismatch { name, expect, got } => {                 write!(f, "包 {} 校验和不匹配: 期望 {} 实际 {}", name, expect, got)             }             PkgError::InstallFailed { name, reason } => write!(f, "安装 {} 失败: {}", name, reason),             PkgError::InvalidRepo { reason } => write!(f, "仓库无效: {}", reason),             PkgError::Io { reason } => write!(f, "IO 错误: {}", reason),         }     } }  pub type PkgResult<T> = Result<T, PkgError>;  // ======================================================================== // 最小 JSON 读写（手写，避免 serde 依赖） // ========================================================================  /// 对字符串进行 JSON 转义。 fn json_escape(s: &str) -> String {     let mut out = String::with_capacity(s.len() + 4);     out.push('"');     for ch in s.chars() {         match ch {             '"' => out.push_str("\\\""),             '\\' => out.push_str("\\\\"),             '\n' => out.push_str("\\n"),             '\r' => out.push_str("\\r"),             '\t' => out.push_str("\\t"),             c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),             c => out.push(c),         }     }     out.push('"');     out }  /// 解析一个 JSON 字符串字面量，返回 (内容, 结束索引，不含结尾引号)。 fn parse_json_string(s: &str, start: usize) -> Option<(String, usize)> {     let bytes = s.as_bytes();     if bytes.get(start) != Some(&b'"') {         return None;     }     let mut out = String::new();     let mut i = start + 1;     while i < bytes.len() {         match bytes[i] {             b'\\' => {                 if i + 1 >= bytes.len() {                     return None;                 }                 match bytes[i + 1] {                     b'"' => out.push('"'),                     b'\\' => out.push('\\'),                     b'n' => out.push('\n'),                     b'r' => out.push('\r'),                     b't' => out.push('\t'),                     b'u' => {                         if i + 6 > bytes.len() {                             return None;                         }                         let hex = std::str::from_utf8(&bytes[i + 2..i + 6]).ok()?;                         let code = u32::from_str_radix(hex, 16).ok()?;                         out.push(std::char::from_u32(code)?);                         i += 5;                     }                     _ => out.push(bytes[i + 1] as char),                 }                 i += 2;             }             b'"' => return Some((out, i + 1)),             c => {                 out.push(c as char);                 i += 1;             }         }     }     None }  /// 跳过 JSON 中的空白。 fn skip_ws(s: &str, mut i: usize) -> usize {     let bytes = s.as_bytes();     while i < bytes.len() && matches!(bytes[i], b' ' | b'\n' | b'\r' | b'\t') {         i += 1;     }     i }  /// 解析 JSON 对象为 (键, 值字符串原片) 列表（仅处理扁平字符串值）。 fn parse_json_object_fields(s: &str, start: usize) -> Option<Vec<(String, String)>> {     let bytes = s.as_bytes();     if bytes.get(start) != Some(&b'{') {         return None;     }     let mut i = skip_ws(s, start + 1);     let mut fields = Vec::new();     if bytes.get(i) == Some(&b'}') {         return Some(fields);     }     loop {         let (key, end) = parse_json_string(s, i)?;         i = skip_ws(s, end);         if bytes.get(i) != Some(&b':') {             return None;         }         i = skip_ws(s, i + 1);         let (val, end) = parse_json_string(s, i)?;         fields.push((key, val));         i = skip_ws(s, end);         match bytes.get(i) {             Some(&b',') => {                 i = skip_ws(s, i + 1);             }             Some(&b'}') => {                 return Some(fields);             }             _ => return None,         }     } }  /// 将扁平字段对象序列化为 JSON 对象字符串。 fn json_object(fields: &[(String, String)]) -> String {     let mut out = String::from("{");     for (i, (k, v)) in fields.iter().enumerate() {         if i > 0 {             out.push(',');         }         out.push_str(&json_escape(k));         out.push(':');         out.push_str(v);     }     out.push('}');     out }  /// 将字符串数组序列化为 JSON 数组。 fn json_array(values: &[String]) -> String {     let mut out = String::from("[");     for (i, v) in values.iter().enumerate() {         if i > 0 {             out.push(',');         }         out.push_str(&json_escape(v));     }     out.push(']');     out }  // ======================================================================== // 数据模型 // ========================================================================  /// 软件包元数据（仓库中可用）。 #[derive(Clone, Debug)] pub struct Package {     pub name: String,     pub version: String,     pub description: String,     pub dependencies: Vec<String>, // "name" 或 "name>=1.0" 简化形式     pub download_url: String,     pub checksum: String, // sha256 十六进制     pub install_script: Option<String>,     pub size: u64,        // 字节     pub category: String, }  impl Package {     pub fn new(         name: &str,         version: &str,         description: &str,         download_url: &str,         checksum: &str,         category: &str,     ) -> Self {         Self {             name: name.to_string(),             version: version.to_string(),             description: description.to_string(),             dependencies: Vec::new(),             download_url: download_url.to_string(),             checksum: checksum.to_string(),             install_script: None,             size: 0,             category: category.to_string(),         }     }      /// 序列化为扁平 JSON 对象字符串。     pub fn to_json(&self) -> String {         json_object(&[             ("name".to_string(), json_escape(&self.name)),             ("version".to_string(), json_escape(&self.version)),             ("description".to_string(), json_escape(&self.description)),             (                 "dependencies".to_string(),                 json_array(&self.dependencies),             ),             (                 "download_url".to_string(),                 json_escape(&self.download_url),             ),             ("checksum".to_string(), json_escape(&self.checksum)),             (                 "install_script".to_string(),                 match &self.install_script {                     Some(s) => json_escape(s),                     None => "null".to_string(),                 },             ),             ("size".to_string(), self.size.to_string()),             ("category".to_string(), json_escape(&self.category)),         ])     }      /// 从扁平 JSON 对象字段反序列化。     fn from_fields(fields: &[(String, String)]) -> Option<Self> {         let get = |key: &str| -> Option<String> {             fields                 .iter()                 .find(|(k, _)| k == key)                 .map(|(_, v)| v.clone())         };         let name = get("name")?;         let version = get("version")?;         let description = get("description")?;         let download_url = get("download_url")?;         let checksum = get("checksum")?;         let size = get("size").and_then(|s| s.parse().ok()).unwrap_or(0);         let category = get("category").unwrap_or_else(|| "misc".to_string());         let install_script = get("install_script");         let install_script = install_script.as_ref().map(|s| {             if s == "null" { None } else { Some(s.clone()) }         }).unwrap_or(None);         let dependencies = match get("dependencies") {             Some(arr) => parse_json_string_array(&arr),             None => Vec::new(),         };         Some(Self {             name,             version,             description,             dependencies,             download_url,             checksum,             install_script,             size,             category,         })     } }  /// 解析 JSON 字符串数组（如 `["a","b"]`）。 fn parse_json_string_array(s: &str) -> Vec<String> {     let s = s.trim();     if s == "[]" || s == "null" {         return Vec::new();     }     let bytes = s.as_bytes();     if bytes.first() != Some(&b'[') || bytes.last() != Some(&b']') {         return Vec::new();     }     let inner = &s[1..s.len() - 1];     if inner.trim().is_empty() {         return Vec::new();     }     inner         .split(',')         .filter_map(|item| {             let item = item.trim();             let (val, _end) = parse_json_string(item, 0)?;             Some(val)         })         .collect() }  /// 软件包简要信息（供搜索结果展示）。 #[derive(Clone, Debug)] pub struct PackageInfo {     pub name: String,     pub available_versions: Vec<String>,     pub installed_version: Option<String>,     pub description: String,     pub category: String,     pub dep_status: DepStatus, }  /// 依赖状态。 #[derive(Clone, Copy, Debug, PartialEq, Eq)] pub enum DepStatus {     /// 所有依赖均已满足。     Satisfied,     /// 有依赖缺失。     Missing,     /// 处于循环依赖中。     Cycle,     /// 依赖未知（仓库中未索引）。     Unknown, }  impl std::fmt::Display for DepStatus {     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {         match self {             DepStatus::Satisfied => write!(f, "已满足"),             DepStatus::Missing => write!(f, "缺失依赖"),             DepStatus::Cycle => write!(f, "循环依赖"),             DepStatus::Unknown => write!(f, "未知依赖"),         }     } }  /// 已安装包记录（本地包数据库条目）。 #[derive(Clone, Debug)] pub struct InstalledPackage {     pub name: String,     pub version: String,     pub install_path: PathBuf,     pub size: u64,     pub installed_at: String, // ISO-8601 占位字符串     pub checksum: String, }  impl InstalledPackage {     pub fn to_json(&self) -> String {         json_object(&[             ("name".to_string(), json_escape(&self.name)),             ("version".to_string(), json_escape(&self.version)),             (                 "install_path".to_string(),                 json_escape(&self.install_path.to_string_lossy()),             ),             ("size".to_string(), self.size.to_string()),             ("installed_at".to_string(), json_escape(&self.installed_at)),             ("checksum".to_string(), json_escape(&self.checksum)),         ])     }      fn from_fields(fields: &[(String, String)]) -> Option<Self> {         let get = |key: &str| -> Option<String> {             fields.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())         };         let name = get("name")?;         let version = get("version")?;         let install_path = get("install_path").map(PathBuf::from).unwrap_or_default();         let size = get("size").and_then(|s| s.parse().ok()).unwrap_or(0);         let installed_at = get("installed_at").unwrap_or_default();         let checksum = get("checksum").unwrap_or_default();         Some(Self {             name,             version,             install_path,             size,             installed_at,             checksum,         })     } }  // ======================================================================== // 本地包数据库（JSON 文件） // ========================================================================  /// 已安装包数据库：名称 -> InstalledPackage，持久化为 JSON 数组文件。 struct PackageDB {     path: PathBuf,     installed: BTreeMap<String, InstalledPackage>, }  impl PackageDB {     fn new(path: PathBuf) -> Self {         Self {             path,             installed: BTreeMap::new(),         }     }      /// 从磁盘加载（文件不存在则返回空数据库）。     fn load(path: &Path) -> Self {         let mut db = Self::new(path.to_path_buf());         if let Ok(data) = fs::read_to_string(path) {             if let Some(packages) = parse_json_installed_array(&data) {                 for p in packages {                     db.installed.insert(p.name.clone(), p);                 }             }         }         db     }      /// 持久化到磁盘。     fn save(&self) -> PkgResult<()> {         if let Some(parent) = self.path.parent() {             let _ = fs::create_dir_all(parent);         }         let mut entries: Vec<String> = self             .installed             .values()             .map(|p| p.to_json())             .collect();         entries.sort();         let content = format!("[{}]", entries.join(","));         fs::write(&self.path, content).map_err(|e| PkgError::Io { reason: e.to_string() })     }      fn get(&self, name: &str) -> Option<&InstalledPackage> {         self.installed.get(name)     }      fn insert(&mut self, pkg: InstalledPackage) {         self.installed.insert(pkg.name.clone(), pkg);     }      fn remove(&mut self, name: &str) -> Option<InstalledPackage> {         self.installed.remove(name)     }      fn list(&self) -> Vec<InstalledPackage> {         self.installed.values().cloned().collect()     } }  /// 解析 JSON 数组形式的已安装包列表。 fn parse_json_installed_array(s: &str) -> Option<Vec<InstalledPackage>> {     let s = s.trim();     if s == "[]" || s.is_empty() {         return Some(Vec::new());     }     let bytes = s.as_bytes();     if bytes.first() != Some(&b'[') || bytes.last() != Some(&b']') {         return None;     }     let inner = &s[1..s.len() - 1];     // 切分顶层对象（按未嵌套的逗号）。     let mut objects = Vec::new();     let mut depth = 0;     let mut cur = String::new();     for ch in inner.chars() {         match ch {             '{' => { depth += 1; cur.push(ch); }             '}' => { depth -= 1; cur.push(ch); }             ',' if depth == 0 => {                 objects.push(std::mem::take(&mut cur));             }             c => cur.push(c),         }     }     if !cur.trim().is_empty() {         objects.push(cur);     }     let mut out = Vec::new();     for obj in objects {         let obj = obj.trim();         if obj.is_empty() {             continue;         }         let fields = parse_json_object_fields(obj, 0)?;         out.push(InstalledPackage::from_fields(&fields)?);     }     Some(out) }  // ======================================================================== // 仓库索引（本地缓存） // ========================================================================  /// 仓库索引：包名称 -> 可用版本列表（版本 -> Package）。 struct RepoIndex {     packages: HashMap<String, BTreeMap<String, Package>>, }  impl RepoIndex {     fn new() -> Self {         Self {             packages: HashMap::new(),         }     }      fn insert(&mut self, pkg: Package) {         self.packages             .entry(pkg.name.clone())             .or_default()             .insert(pkg.version.clone(), pkg);     }      fn get(&self, name: &str, version: &str) -> Option<&Package> {         self.packages.get(name).and_then(|v| v.get(version))     }      fn latest(&self, name: &str) -> Option<&Package> {         self.packages.get(name).and_then(|v| v.values().next_back())     }      fn names(&self) -> Vec<String> {         let mut names: Vec<String> = self.packages.keys().cloned().collect();         names.sort();         names     }      fn len(&self) -> usize {         self.packages.values().map(|v| v.len()).sum()     }      fn is_empty(&self) -> bool {         self.packages.is_empty()     } }  // ======================================================================== // 包管理器主体 // ========================================================================  /// 包管理器主入口。 /// /// * `new(repo_url)` —— 创建并绑定仓库 URL 与本地缓存/数据库路径； /// * `refresh_repo()` —— 刷新仓库索引（模拟从远端拉取，写入本地缓存）； /// * `search(query)` —— 搜索可用包； /// * `install(name)` —— 依赖解析 → 下载 → 校验 → 解压 → 安装脚本 → 写入包数据库； /// * `remove(name)` —— 移除并更新包数据库； /// * `upgrade(name)` / `upgrade_all()` —— 升级到最新版本； /// * `list_installed()` —— 列出已安装包。 pub struct PackageManager {     repo_url: String,     cache_dir: PathBuf,     db_path: PathBuf,     index: RepoIndex, }  impl PackageManager {     /// 创建包管理器。     ///     /// * `repo_url`：仓库索引地址（本实现将其作为缓存目录名的一部分，模拟远端）；     /// * `cache_dir`：本地仓库索引缓存目录；     /// * `db_path`：已安装包数据库 JSON 文件路径。     pub fn new(repo_url: &str, cache_dir: &Path, db_path: &Path) -> Self {         Self {             repo_url: repo_url.to_string(),             cache_dir: cache_dir.to_path_buf(),             db_path: db_path.to_path_buf(),             index: RepoIndex::new(),         }     }      /// 刷新仓库索引：模拟从远端下载索引并写入本地缓存。     ///     /// 离线原型中直接种子化一批内置包；真实环境中此处应执行 HTTP GET。     pub fn refresh_repo(&mut self) -> PkgResult<()> {         let _ = fs::create_dir_all(&self.cache_dir);         let index_path = self.cache_dir.join("index.json");          // 种子索引（模拟远端仓库）。         let seed = [             (                 "libc",                 "2.35",                 "标准 C 库",                 "https://repo.hibos.dev/libc-2.35.tar.xz",                 "a1b2c3d4",                 "system",                 850,                 Vec::new(),             ),             (                 "libgpu",                 "1.2.0",                 "GPU 驱动库",                 "https://repo.hibos.dev/libgpu-1.2.0.tar.xz",                 "e5f6a7b8",                 "driver",                 4096,                 vec!["libc"],             ),             (                 "ai-runtime",                 "0.9.1",                 "AI 推理运行时",                 "https://repo.hibos.dev/ai-runtime-0.9.1.tar.xz",                 "11223344",                 "ai",                 15360,                 vec!["libgpu", "libc"],             ),             (                 "wl-compositor",                 "2.0.3",                 "Wayland 合成器",                 "https://repo.hibos.dev/wl-compositor-2.0.3.tar.xz",                 "55667788",                 "desktop",                 8192,                 vec!["libc", "libgpu"],             ),             (                 "netd",                 "1.4.0",                 "网络守护进程",                 "https://repo.hibos.dev/netd-1.4.0.tar.xz",                 "99aabbcc",                 "net",                 2048,                 vec!["libc"],             ),             (                 "hibos-tools",                 "0.1.0",                 "Hib OS 工具集",                 "https://repo.hibos.dev/hibos-tools-0.1.0.tar.xz",                 "ddeeff00",                 "tools",                 512,                 vec![],             ),         ];         let mut index = RepoIndex::new();         for (name, ver, desc, url, sum, cat, size, deps) in seed {             let mut pkg = Package::new(name, ver, desc, url, sum, cat);             pkg.size = size;             pkg.dependencies = deps.iter().map(|s| s.to_string()).collect();             index.insert(pkg);         }          // 持久化索引缓存（JSON 数组）。         let mut entries: Vec<String> = index             .packages             .values()             .flat_map(|v| v.values())             .map(|p| p.to_json())             .collect();         entries.sort();         fs::write(&index_path, format!("[{}]", entries.join(",")))             .map_err(|e| PkgError::Io { reason: e.to_string() })?;          self.index = index;         Ok(())     }      /// 搜索仓库中匹配查询的包。     pub fn search(&self, query: &str) -> Vec<PackageInfo> {         let installed = PackageDB::load(&self.db_path);         let q = query.to_lowercase();         let mut results: Vec<PackageInfo> = Vec::new();         for name in self.index.names() {             if q.is_empty() || name.contains(&q) {                 if let Some(latest) = self.index.latest(&name) {                     let installed_version = installed.get(&name).map(|p| p.version.clone());                     let dep_status = Self::dep_status_for(&name, &self.index, &installed);                     results.push(PackageInfo {                         name: name.clone(),                         available_versions: self                             .index                             .packages                             .get(&name)                             .map(|v| v.keys().cloned().collect())                             .unwrap_or_default(),                         installed_version,                         description: latest.description.clone(),                         category: latest.category.clone(),                         dep_status,                     });                 }             }         }         results.sort_by(|a, b| a.name.cmp(&b.name));         results     }      /// 计算某包的依赖状态。     fn dep_status_for(         name: &str,         index: &RepoIndex,         installed: &PackageDB,     ) -> DepStatus {         let Some(pkg) = index.latest(name) else {             return DepStatus::Unknown;         };         if pkg.dependencies.is_empty() {             return DepStatus::Satisfied;         }         for dep in &pkg.dependencies {             let dep_name = dep.split(&['>', '<', '=', '!'][..]).next().unwrap_or(dep).trim();             if installed.get(dep_name).is_none() {                 return DepStatus::Missing;             }         }         DepStatus::Satisfied     }      /// 安装包（含依赖递归安装）。     pub fn install(&mut self, name: &str) -> PkgResult<()> {         let installed = PackageDB::load(&self.db_path);         if installed.get(name).is_some() {             return Err(PkgError::AlreadyInstalled { name: name.to_string() });         }          // 依赖解析：拓扑排序（依赖先安装）。         let order = Self::resolve_order(name, &self.index)?;         // 检测循环依赖（resolve_order 已在有环时返回 Err）。         let _ = order;          // 按拓扑序安装（依赖在前）。         let mut newly: Vec<String> = Vec::new();         for pkg_name in &order {             if installed.get(pkg_name).is_some() || newly.contains(pkg_name) {                 continue;             }             let pkg = self                 .index                 .latest(pkg_name)                 .ok_or_else(|| PkgError::NotFound { name: pkg_name.clone() })?                 .clone();             self.install_one(&pkg)?;             newly.push(pkg_name.clone());         }         Ok(())     }      /// 解析安装顺序：返回依赖在前的拓扑序；检测环返回 CycleDetected。     fn resolve_order(         start: &str,         index: &RepoIndex,     ) -> PkgResult<Vec<String>> {         // DFS 三色标记拓扑排序 + 环检测。         let mut color: HashMap<String, u8> = HashMap::new(); // 0=未访问,1=进行中,2=完成         let mut order: Vec<String> = Vec::new();         let mut stack: Vec<String> = Vec::new();          Self::dfs_topo(start, index, &mut color, &mut order, &mut stack)?;         order.reverse();         Ok(order)     }      fn dfs_topo(         node: &str,         index: &RepoIndex,         color: &mut HashMap<String, u8>,         order: &mut Vec<String>,         stack: &mut Vec<String>,     ) -> PkgResult<()> {         let c = *color.get(node).unwrap_or(&0);         if c == 2 {             return Ok(());         }         if c == 1 {             // 发现回边：构造环路。             let mut cycle: Vec<String> = stack.iter().skip_while(|s| s.as_str() != node).cloned().collect();             cycle.push(node.to_string());             return Err(PkgError::CycleDetected { cycle });         }         color.insert(node.to_string(), 1);         stack.push(node.to_string());         let pkg = match index.latest(node) {             Some(p) => p,             None => {                 // 未索引的依赖视为叶子（无法继续）。                 color.insert(node.to_string(), 2);                 stack.pop();                 order.push(node.to_string());                 return Ok(());             }         };         for dep in &pkg.dependencies {             let dep_name = dep.split(&['>', '<', '=', '!'][..]).next().unwrap_or(dep).trim();             if dep_name.is_empty() {                 continue;             }             Self::dfs_topo(dep_name, index, color, order, stack)?;         }         color.insert(node.to_string(), 2);         stack.pop();         order.push(node.to_string());         Ok(())     }      /// 安装单个包：模拟下载 → 校验 → 解压 → 安装脚本 → 写入包数据库。     fn install_one(&mut self, pkg: &Package) -> PkgResult<()> {         // 1. 模拟下载到缓存。         let _ = fs::create_dir_all(&self.cache_dir);         let archive = self.cache_dir.join(format!("{}-{}.tar.xz", pkg.name, pkg.version));         fs::write(&archive, b"simulated-archive-contents")             .map_err(|e| PkgError::Io { reason: e.to_string() })?;         // 模拟下载失败概率：校验和固定为种子值，若 URL 不可识别则失败。         if !pkg.download_url.starts_with("https://") {             return Err(PkgError::DownloadFailed {                 url: pkg.download_url.clone(),             });         }          // 2. 校验和（模拟：计算 archive 内容的简单哈希，与 pkg.checksum 比较）。         let got = simple_hash(&fs::read(&archive).map_err(|e| PkgError::Io { reason: e.to_string() })?);         if got != pkg.checksum {             return Err(PkgError::ChecksumMismatch {                 name: pkg.name.clone(),                 expect: pkg.checksum.clone(),                 got,             });         }          // 3. 解压（模拟：创建安装目录）。         let install_path = self.cache_dir.join(format!("installed/{}-{}", pkg.name, pkg.version));         let _ = fs::create_dir_all(&install_path);         fs::write(install_path.join("MANIFEST"), pkg.to_json().as_bytes())             .map_err(|e| PkgError::Io { reason: e.to_string() })?;          // 4. 运行安装脚本（模拟：仅记录）。         if let Some(script) = &pkg.install_script {             let _ = script; // 离线原型中不执行任意脚本。         }          // 5. 写入包数据库。         let mut db = PackageDB::load(&self.db_path);         let now = std::time::SystemTime::now()             .duration_since(std::time::UNIX_EPOCH)             .unwrap_or_default()             .as_secs();         db.insert(InstalledPackage {             name: pkg.name.clone(),             version: pkg.version.clone(),             install_path,             size: pkg.size,             installed_at: format!("{}", now),             checksum: pkg.checksum.clone(),         });         db.save()?;         Ok(())     }      /// 移除包。     pub fn remove(&mut self, name: &str) -> PkgResult<()> {         let mut db = PackageDB::load(&self.db_path);         // 拒绝移除被他人依赖的包（简化：检查仓库中哪些包依赖它）。         let dependents: Vec<String> = self             .index             .packages             .values()             .flat_map(|v| v.values())             .filter(|p| p.dependencies.iter().any(|d| d.starts_with(name)))             .map(|p| p.name.clone())             .collect();         if !dependents.is_empty() {             return Err(PkgError::InstallFailed {                 name: name.to_string(),                 reason: format!("被 {} 依赖，拒绝移除", dependents.join(",")),             });         }         db.remove(name).ok_or_else(|| PkgError::NotFound { name: name.to_string() })?;         db.save()?;         Ok(())     }      /// 升级指定包到最新版本。     pub fn upgrade(&mut self, name: &str) -> PkgResult<()> {         let db = PackageDB::load(&self.db_path);         let installed = db             .get(name)             .ok_or_else(|| PkgError::NotFound { name: name.to_string() })?;         let latest = self             .index             .latest(name)             .ok_or_else(|| PkgError::NotFound { name: name.to_string() })?;         if installed.version == latest.version {             return Ok(()); // 已是最新。         }         // 卸载旧版再安装新版（简化）。         drop(db);         self.remove(name)?;         self.install(name)     }      /// 升级所有已安装包（按依赖拓扑顺序，依赖优先升级）。     pub fn upgrade_all(&mut self) -> PkgResult<()> {         let db = PackageDB::load(&self.db_path);         let names: Vec<String> = db.installed.keys().cloned().collect();         drop(db);         // 按拓扑序：依赖先升级。         let mut ordered: Vec<String> = Vec::new();         let mut visited: BTreeSet<String> = BTreeSet::new();         for name in &names {             Self::upgrade_dfs(name, &self.index, &mut visited, &mut ordered);         }         for name in ordered {             let _ = self.upgrade(&name);         }         Ok(())     }      fn upgrade_dfs(         name: &str,         index: &RepoIndex,         visited: &mut BTreeSet<String>,         ordered: &mut Vec<String>,     ) {         if !visited.insert(name.to_string()) {             return;         }         if let Some(pkg) = index.latest(name) {             for dep in &pkg.dependencies {                 let dep_name = dep.split(&['>', '<', '=', '!'][..]).next().unwrap_or(dep).trim();                 if !dep_name.is_empty() {                     Self::upgrade_dfs(dep_name, index, visited, ordered);                 }             }         }         ordered.push(name.to_string());     }      /// 列出已安装包。     pub fn list_installed(&self) -> Vec<InstalledPackage> {         let mut db = PackageDB::load(&self.db_path);         let mut list = db.list();         list.sort_by(|a, b| a.name.cmp(&b.name));         list     } }  // ======================================================================== // 简单哈希（模拟校验和计算，无加密依赖） // ========================================================================  fn simple_hash(data: &[u8]) -> String {     let mut h: u64 = 14695981039346656037;     for &b in data {         h ^= b as u64;         h = h.wrapping_mul(1099511628211);     }     format!("{:016x}", h) }  // ======================================================================== // 单元测试 // ========================================================================  #[cfg(test)] mod tests {     use super::*;     use std::env;      fn tmp_dir(suffix: &str) -> PathBuf {         let base = env::temp_dir().join(format!("hibos-pkg-test-{}", suffix));         let _ = fs::remove_dir_all(&base);         let _ = fs::create_dir_all(&base);         base     }      #[test]     fn json_escape_and_object_roundtrip() {         let escaped = json_escape(r#"he said "hi" # done"#);         assert!(escaped.contains("\\\""));         let obj = json_object(&[("a".into(), json_escape("b")), ("c".into(), "1".into())]);         assert_eq!(obj, r#"{"a":"b","c":"1"}"#);     }      #[test]     fn parse_json_string_array() {         assert_eq!(parse_json_string_array("[]"), Vec::<String>::new());         assert_eq!(parse_json_string_array(r#"["a","b"]"#), vec!["a".to_string(), "b".to_string()]);         assert_eq!(parse_json_string_array("null"), Vec::<String>::new());     }      #[test]     fn package_to_json_and_fields() {         let mut p = Package::new("foo", "1.0", "desc", "https://x/foo.tar.xz", "deadbeef", "sys");         p.dependencies = vec!["libc".into()];         let json = p.to_json();         assert!(json.contains("\"name\":\"foo\""));         assert!(json.contains("\"version\":\"1.0\""));         assert!(json.contains("\"dependencies\":[\"libc\"]"));         let fields = parse_json_object_fields(&json, 0).unwrap();         let p2 = Package::from_fields(&fields).unwrap();         assert_eq!(p2.name, "foo");         assert_eq!(p2.version, "1.0");         assert_eq!(p2.dependencies, vec!["libc"]);     }      #[test]     fn installed_package_json_roundtrip() {         let ip = InstalledPackage {             name: "bar".into(),             version: "2.0".into(),             install_path: PathBuf::from("/opt/bar-2.0"),             size: 1234,             installed_at: "1234567890".into(),             checksum: "cafebabe".into(),         };         let json = ip.to_json();         let fields = parse_json_object_fields(&json, 0).unwrap();         let ip2 = InstalledPackage::from_fields(&fields).unwrap();         assert_eq!(ip2.name, "bar");         assert_eq!(ip2.version, "2.0");         assert_eq!(ip2.size, 1234);     }      #[test]     fn refresh_and_search() {         let tmp = tmp_dir("refresh");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         assert!(pm.refresh_repo().is_ok());         let results = pm.search("");         assert!(!results.is_empty());         assert!(results.iter().any(|r| r.name == "libc"));         let libc = pm.search("libc");         assert_eq!(libc.len(), 1);         assert_eq!(libc[0].name, "libc");         // 空查询返回全部。         assert_eq!(pm.search("").len(), pm.index.names().len());     }      #[test]     fn install_dependency_order() {         let tmp = tmp_dir("install");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         // ai-runtime 依赖 libgpu -> libc，应先装 libc/libgpu。         assert!(pm.install("ai-runtime").is_ok());         let installed = pm.list_installed();         let names: Vec<String> = installed.iter().map(|p| p.name.clone()).collect();         assert!(names.contains(&"libc".to_string()));         assert!(names.contains(&"libgpu".to_string()));         assert!(names.contains(&"ai-runtime".to_string()));         // 重复安装应失败。         assert_eq!(             pm.install("ai-runtime").unwrap_err(),             PkgError::AlreadyInstalled { name: "ai-runtime".to_string() }         );     }      #[test]     fn install_nonexistent_fails() {         let tmp = tmp_dir("install2");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         assert_eq!(             pm.install("no-such-package").unwrap_err(),             PkgError::NotFound { name: "no-such-package".to_string() }         );     }      #[test]     fn remove_and_upgrade() {         let tmp = tmp_dir("remove");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         pm.install("netd").unwrap();         assert!(pm.list_installed().iter().any(|p| p.name == "netd"));         assert!(pm.remove("netd").is_ok());         assert!(!pm.list_installed().iter().any(|p| p.name == "netd"));         // 移除不存在。         assert_eq!(             pm.remove("nope").unwrap_err(),             PkgError::NotFound { name: "nope".to_string() }         );         // 被依赖的包拒绝移除（libc 被 libgpu 等依赖）。         pm.install("libc").unwrap();         assert!(pm.remove("libc").is_err());     }      #[test]     fn cycle_detection() {         let tmp = tmp_dir("cycle");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         // 人工注入循环：a -> b -> a。         let mut a = Package::new("pkg-a", "1.0", "a", "https://x/a", "aaaa", "sys");         a.dependencies = vec!["pkg-b".into()];         let mut b = Package::new("pkg-b", "1.0", "b", "https://x/b", "bbbb", "sys");         b.dependencies = vec!["pkg-a".into()];         pm.index.insert(a);         pm.index.insert(b);         let err = pm.install("pkg-a").unwrap_err();         assert!(matches!(err, PkgError::CycleDetected { .. }));     }      #[test]     fn dep_status() {         let tmp = tmp_dir("status");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         // libgpu 依赖 libc，尚未安装 -> Missing。         assert_eq!(             pm.dep_status_for("libgpu", &pm.index, &PackageDB::load(&db)),             DepStatus::Missing         );         pm.install("libc").unwrap();         let installed = PackageDB::load(&db);         assert_eq!(             pm.dep_status_for("libgpu", &pm.index, &installed),             DepStatus::Satisfied         );         assert_eq!(             pm.dep_status_for("nope", &pm.index, &PackageDB::load(&db)),             DepStatus::Unknown         );     }      #[test]     fn package_info_search() {         let tmp = tmp_dir("info");         let cache = tmp.join("cache");         let db = tmp.join("db.json");         let mut pm = PackageManager::new("https://repo.hibos.dev", &cache, &db);         pm.refresh_repo().unwrap();         pm.install("hibos-tools").unwrap();         let infos = pm.search("tools");         assert!(!infos.is_empty());         let info = &infos[0];         assert_eq!(info.name, "hibos-tools");         assert!(info.installed_version.is_some());         assert_eq!(info.dep_status, DepStatus::Satisfied);     }      #[test]     fn simple_hash_deterministic() {         let h1 = simple_hash(b"hello");         let h2 = simple_hash(b"hello");         assert_eq!(h1, h2);         assert_ne!(simple_hash(b"hello"), simple_hash(b"world"));     } }